-- SOLO LECTURA. No ejecutar migraciones/importaciones mediante este archivo.
SELECT type,name,sql FROM sqlite_master WHERE name IN ('publications','juntas_document_revisions','idx_juntas_revisions_publication','idx_juntas_notices_date','trg_juntas_revision_created','trg_juntas_revision_previous','trg_juntas_revision_changed','juntas_import_checkpoint','juntas_import_applied','import_gateway_identity');
SELECT database_name,database_id FROM import_gateway_identity WHERE id=1;
SELECT root_id,category,status,last_attempt_at,last_success_at,error_code,length(state_json) AS state_chars,lease_until FROM juntas_import_checkpoint ORDER BY root_id;
SELECT root_id,count(*) AS signatures FROM juntas_import_applied GROUP BY root_id;
SELECT count(*) AS active_leases FROM import_gate_lease WHERE expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now');
SELECT id,external_id,junta,category,official_url,length(summary) AS summary_chars FROM publications WHERE source='Padrones y Comunicados' AND (id IN ('drive:pad-secundaria:1DYDvL-Rq7eJKv8nTMhUv0_EV3cvG_eSG','drive:pad-secundaria:1OJnSOWltTljQGDBGtfOG5bPIFpRa-eZd','drive:pad-secundaria:1RJueu9MRfHgRpzE0mq9senJ8WIfW1uOr','drive:pad-secundaria:1UPTvqA53yvGaY7HbUGeRLuVSGihavNXe','drive:pad-secundaria:1dFFJoeIMKjBmFgi0kCW2cJ-bX5WjjRcD','drive:pad-secundaria:1u8kXSIzLM4RC-HB9dI0_hZxsVf2PlZN9','drive:pad-tecnica:10acRd9DcGRx6S8jpt1ih269U30RbFb4y','drive:pad-tecnica:1EEKyEPaQGBQWMchy2EX-HlBCVjNLYzqC','drive:pad-tecnica:1F0chjihrmHkiN2X52Ut18xhj-3t5qHTQ','drive:pad-tecnica:1LVwoXrIj1KgyWf1n7fm7eI1n-5qNSfmb','drive:pad-tecnica:1SHZnZDD92HsDR60yQsCc11_iVY5j3ZTs','drive:pad-tecnica:1TWFgAbZ8bV7SPLMrFinTJ8UdkplJhAJ6','drive:pad-tecnica:1nSrVDg8FDtO4mb2FR7lOXnwe8r6yjFVb','drive:pad-tecnica:1yVo1PGywHSHeQ2rZyTNP0lkb8px1VoxW') OR official_url IN ('https://drive.google.com/file/d/1DYDvL-Rq7eJKv8nTMhUv0_EV3cvG_eSG/view','https://drive.google.com/file/d/1OJnSOWltTljQGDBGtfOG5bPIFpRa-eZd/view','https://drive.google.com/file/d/1RJueu9MRfHgRpzE0mq9senJ8WIfW1uOr/view','https://drive.google.com/file/d/1UPTvqA53yvGaY7HbUGeRLuVSGihavNXe/view','https://drive.google.com/file/d/1dFFJoeIMKjBmFgi0kCW2cJ-bX5WjjRcD/view','https://drive.google.com/file/d/1u8kXSIzLM4RC-HB9dI0_hZxsVf2PlZN9/view','https://drive.google.com/file/d/10acRd9DcGRx6S8jpt1ih269U30RbFb4y/view','https://drive.google.com/file/d/1EEKyEPaQGBQWMchy2EX-HlBCVjNLYzqC/view','https://drive.google.com/file/d/1F0chjihrmHkiN2X52Ut18xhj-3t5qHTQ/view','https://drive.google.com/file/d/1LVwoXrIj1KgyWf1n7fm7eI1n-5qNSfmb/view','https://drive.google.com/file/d/1SHZnZDD92HsDR60yQsCc11_iVY5j3ZTs/view','https://drive.google.com/file/d/1TWFgAbZ8bV7SPLMrFinTJ8UdkplJhAJ6/view','https://drive.google.com/file/d/1nSrVDg8FDtO4mb2FR7lOXnwe8r6yjFVb/view','https://drive.google.com/file/d/1yVo1PGywHSHeQ2rZyTNP0lkb8px1VoxW/view')) ORDER BY id;

